package org.telegram.ui.Components.Paint;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

import org.telegram.messenger.R;

/** Exact WebP stamp payloads from Nekogram revision e924154e. */
final class BrushAssets {
    private static final String RADIAL =
            "";
    private static final String ELLIPTICAL =
            "";
    private static final String NEON =
            "";

    private BrushAssets() {}

    static Bitmap decode(int id) {
        String encoded = id == R.drawable.paint_elliptical_brush ? ELLIPTICAL
                : id == R.drawable.paint_neon_brush ? NEON : RADIAL;
        byte[] bytes = Base64.decode(encoded, Base64.DEFAULT);
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
    }
}
